(()=>{const d=document.getElementById('chrom-dialog');document.querySelectorAll('.chrom-enlarge').forEach(b=>b.addEventListener('click',()=>{const i=b.querySelector('img');document.getElementById('chrom-image').src=i.src;document.getElementById('chrom-image').alt=i.alt;document.getElementById('chrom-title').textContent=b.closest('figure').querySelector('figcaption').textContent;d.showModal();}));document.getElementById('chrom-close').onclick=()=>d.close();})();